"""Eleven separately authored vector landscapes; shared brushes, independent drawings."""
import json,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'web/assets/maps'
def path(d,fill='none',stroke='none',width=1,extra=''):
 return f'<path d="{d}" fill="{fill}" stroke="{stroke}" stroke-width="{width}" stroke-linecap="round" stroke-linejoin="round" {extra}/>'
def ridge(points,color,ice=False):
 s=''
 for x,y,w,h in points:
  s+=path(f'M{x-w} {y+45} L{x-w*.45} {y-25} L{x} {y-h} L{x+w*.40} {y-15} L{x+w} {y+45} Z',color,'#ffffff',2, 'opacity=".84"')
  s+=path(f'M{x} {y-h} L{x+w*.20} {y+40} L{x+w} {y+45} Z','#253c43',extra='opacity=".20"')
  s+=path(f'M{x-w*.28} {y-h*.45} L{x} {y-h} L{x+w*.22} {y-h*.55}','#eaf0e7' if ice else '#f3e2c9',extra='opacity=".78"')
 return s
def grove(points,color,kind='tree'):
 s=''
 for x,y,size in points:
  if kind=='bamboo':
   for dx,h in [(-18,100),(0,135),(22,112)]:
    s+=path(f'M{x+dx} {y} v{-h}',stroke=color,width=7)
    s+=path(f'M{x+dx} {y-h*.6} q-40 -40 -60 -24 M{x+dx} {y-h*.8} q45 -35 64 -18',stroke=color,width=8)
  elif kind=='mushroom':
   s+=path(f'M{x} {y} v{-size*.85}',stroke=color,width=10)
   s+=path(f'M{x-size} {y-size*.75} Q{x-size*.8} {y-size*1.75} {x} {y-size*1.8} Q{x+size*.9} {y-size*1.6} {x+size} {y-size*.75} Q{x} {y-size*.5} {x-size} {y-size*.75} Z',color,'#ece2db',3)
  else:
   s+=path(f'M{x} {y} v{-size}',stroke='#725f4e',width=7)
   if kind=='pine':s+=path(f'M{x} {y-size*2} l{-size*.75} {size*1.3} h{size*.4} l{-size*.7} {size*.7} h{size*2.1} l{-size*.7} {-size*.7} h{size*.4} Z',color)
   else:s+=f'<ellipse cx="{x}" cy="{y-size*1.2}" rx="{size*.75}" ry="{size}" fill="{color}" opacity=".85"/>'
 return s
def shoreline_detail(points, signature):
 # Small coves and rock heads follow a hand-drawn geographic coast, not a radial base.
 # Deterministic brush variation is local to artwork; no simulation RNG is involved.
 result=[]
 for i,a in enumerate(points):
  b=points[(i+1)%len(points)];dx=b[0]-a[0];dy=b[1]-a[1];length=math.hypot(dx,dy)
  result.append(a)
  count=min(5,max(1,int(length/55)))
  for j in range(1,count):
   code=(signature*31+i*47+j*29)%101
   t=(j+(code%7-3)*.045)/count
   offset=(code%39-19)*min(1,length/170)
   result.append([round(a[0]+dx*t-dy/length*offset,2),round(a[1]+dy*t+dx/length*offset,2)])
 return result

def coast_path(points):
 # Retain deliberately sharp, uneven vertices; no common circle or corner smoothing.
 d='M'+' L'.join(f'{x} {y}' for x,y in points)+' Z'
 samples=[]
 for i,a in enumerate(points):
  b=points[(i+1)%len(points)]
  for j in range(1):
   t=j;samples.append([round(a[0]+(b[0]-a[0])*t,2),round(a[1]+(b[1]-a[1])*t,2)])
 return d,samples

