LANDMARK_GROUNDS={"human":[[-1050,-1040,-140,-150],[490,-300,780,-80],[50,620,820,950]],"demon":[[-730,0,-340,400],[550,200,1040,730]],"spirit":[[-880,-900,-160,-330],[240,-850,630,-640]],"true_demon":[[-720,-740,710,340],[320,270,730,920]],"monster_realm":[[-1000,-850,1110,-280],[-1090,70,-410,640]],"phantom_underworld":[[-820,-1010,-60,-400],[420,140,1100,790]],"hell":[[-690,0,50,300],[410,570,840,820]],"celestial":[[-750,-890,910,740],[740,180,990,500],[-1020,-1050,-590,-730],[-820,570,-490,860]],"asura":[[-720,260,-300,570],[160,-810,540,-490],[370,180,810,520]],"nether":[[-800,-1300,850,-180]],"reincarnation":[[-480,-690,620,360]]}

def inside(point, ring):
 x,y=point;result=False
 for i,a in enumerate(ring):
  b=ring[(i+1)%len(ring)]
  if (a[1]>y)!=(b[1]>y) and x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]:result=not result
 return result

def simple_ring(ring):
 def cross(a,b,c):return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
 for i,a in enumerate(ring):
  b=ring[(i+1)%len(ring)]
  for j in range(i+2,len(ring)):
   if i==0 and j==len(ring)-1:continue
   c=ring[j];d=ring[(j+1)%len(ring)]
   if cross(a,b,c)*cross(a,b,d)<0 and cross(c,d,a)*cross(c,d,b)<0:return False
 return True

def geographic_outline(id, original):
 coast=[[round(x*1.12,2),round(y*1.12,2)] for x,y in original]
 # Reserve the portion of each landmark's ground already present in the original map.
 protected=[]
 for x0,y0,x1,y1 in LANDMARK_GROUNDS[id]:
  for ix in range(13):
   for iy in range(13):
    p=[x0+(x1-x0)*ix/12,y0+(y1-y0)*iy/12]
    if inside(p,original):protected.append(p)
 # Process backwards so each edit continues to refer to an authored original edge.
 for index,depth in sorted(((int(k),v) for k,v in COAST_EDITS[id].items()),reverse=True):
  a=coast[index];b=coast[(index+1)%len(coast)]
  dx=b[0]-a[0];dy=b[1]-a[1];length=math.hypot(dx,dy)
  for scale in [1,.72,.45,.22,0]:
   inset=depth*scale
   additions=[]
   for t,offset in [(.18,0),(.33,inset*.62),(.48,inset),(.67,inset*.84),(.82,0)]:
    additions.append([round(a[0]+dx*t-dy/length*offset,2),round(a[1]+dy*t+dx/length*offset,2)])
   candidate=coast[:index+1]+additions+coast[index+1:]
   if simple_ring(candidate) and all(inside(p,candidate) for p in protected):
    coast=candidate;break
 return coast

