def build():
 OUT.mkdir(parents=True,exist_ok=True);manifest={}
 for id,d in W.items():
  signature=sum(ord(c) for c in id)
  detailed=shoreline_detail(d['outline'],signature)
  if not simple_ring(detailed):detailed=d['outline']
  coast,samples=coast_path(detailed);rings=[samples]
  for shard in d['shards']:
   fragment,vertices=coast_path(shoreline_detail(shard,signature+97));coast+=' '+fragment;rings.append(vertices)
  a,b=d['land']
  svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="-1800 -1800 3600 3600" data-world="{id}"><title>{d["name"]}</title><metadata>'+json.dumps(dict(world=id,landmarks=d['landmarks']),ensure_ascii=False)+f'</metadata><defs><linearGradient id="{id}-land" x2=".7" y2="1"><stop stop-color="{a}"/><stop offset="1" stop-color="{b}"/></linearGradient><clipPath id="{id}-coast"><path d="{coast}"/></clipPath></defs>'
  svg+=path(coast,f'url(#{id}-land)',d['cliff'],7)
  svg+=f'<g clip-path="url(#{id}-coast)">'+d['features']+'</g>'
  svg+=path(coast,stroke='#f2ebd2',width=15,extra='opacity=".54"')+'</svg>'
  (OUT/f'{id}.svg').write_text(svg,encoding='utf8')
  manifest[id]=dict(url=f'/assets/maps/{id}.svg?v=2132',name=d['name'],sea=d['sea'],cliff=d['cliff'],outline=samples,outlines=rings,x=-1800,y=-1800,width=3600,height=3600)
 target=ROOT/'web/map-artwork-data.js'
 target.write_text('/* Individually authored landscapes. Generated by tools/build_map_artwork.py. */\nwindow.MapArtworkData='+json.dumps(manifest,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf8')
 print('Eleven distinct vector landscapes and projection manifest written')
if __name__=='__main__':build()
